pub fn terminal_qm31(
            self,
            claims: &[[QM31; 29]; 3],
            alpha: &[QM31; 10],
            c: &Challenges,
        ) -> Result<QM31, Error> {
            let mut selected=[QM31::ZERO;84];let mut i=0usize;while i<84 {selected[i]=claims[i/28][i%28];i+=1;}
            match terminal_parts(
                self.semantic(),
                &selected,
                alpha,
                c.lambda,
                c.chi,
                c.theta,
                &c.zc,
                c.mu,
            ) {Ok(parts)=>Ok(parts.0),Err(_)=>Err(Error::Public)}
        }

fn composition_parts(
    public: SemanticPublic,
    claims: &[QM31; POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_CLAIMS_V1],
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    theta: QM31,
) -> Result<
    (
        QM31,
        [QM31; 16],
        [QM31; STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS],
        QM31,
        QM31,
        QM31,
    ),
    PoolV1PairForestSemanticTerminalErrorV1,
> {
    let invalid_amount = match public.withdrawal_amount {
        None => false,
        Some(amount) => amount == 0 || amount >= (1 << 30u32),
    };
    if invalid_amount {
        return Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidPublicAmount);
    }
    validate_transition(public)?;
    let openings = StateOnlyPoseidonOpenings {
        z: qm31_array!(16, column, selected_claim(claims, 0, column)),
        succ_z: qm31_array!(16, column, selected_claim(claims, 1, column)),
        xor12_z: qm31_array!(16, column, selected_claim(claims, 2, column)),
    };
    let mask_only = qm31_array!(STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS, column, {
        selected_claim(
            claims,
            0,
            POOL_V1_PAIR_FOREST_TERMINAL_C1_COLUMNS_V1 + column,
        )
    });
    let selectors = Selectors::boxed_at_point(point);
    let poseidon =
        evaluate_state_only_poseidon_oracle_projected(&openings, &poseidon_selectors(&selectors));
    let semantic = semantic_packed(public, &openings, &selectors);
    let h1_z = selected_claim(claims, 0, SELECTED_H1_COLUMN);
    let copy = evaluate_with_selectors(
        &openings.z,
        h1_z,
        &selectors,
        lambda,
        chi,
        public.transition.live_snapshot.next_pair_index,
        copy_variant(public.variant),
    );
    let prepared_theta = PreparedQm31Multiplier::new(theta);
    let mut composition = copy.residual;
    let mut index = semantic.len();
    while index > 0 {
        index -= 1;
        composition = prepared_theta.mul(composition).add(semantic[index]);
    }
    index = poseidon.len();
    while index > 0 {
        index -= 1;
        composition = prepared_theta.mul(composition).add(poseidon[index]);
    }
    Ok((
        composition,
        openings.z,
        mask_only,
        selected_claim(claims, 0, SELECTED_G_COLUMN),
        h1_z,
        copy.active,
    ))
}

fn equality_value(left: &[QM31; 10], right: &[QM31; 10]) -> QM31 {
    let mut product = equality_factor(left[0], right[0]);
    let mut index = 1usize;
    while index < left.len() {
        product = product.mul(equality_factor(left[index], right[index]));
        index += 1;
    }
    product
}

fn validate_transition(
    public: SemanticPublic,
) -> Result<(), PoolV1PairForestSemanticTerminalErrorV1> {
    let source = public.transition.live_snapshot;
    let after = public.transition.candidate_afterstate;
    if source.pool != public.pool
        || source.deployment_domain != public.deployment_domain
        || source.sequence != source.next_pair_index
        || source.next_pair_index >= POOL_V1_PAIR_CAPACITY
        || source.next_pair_index.checked_add(1) != Some(after.next_pair_index)
    {
        return Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition);
    }
    let index = source.next_pair_index;
    let carry = bounded_append_carry(index);
    for level in 0..20 {
        if level == carry && carry < 20 {
            continue;
        }
        let expected = if level < carry || ((index >> level) & 1) == 0 {
            empty_root(level)
        } else {
            source.frontier[level]
        };
        if after.next_frontier[level] != expected {
            return Err(PoolV1PairForestSemanticTerminalErrorV1::InvalidAppendTransition);
        }
    }
    Ok(())
}

fn selected_claim(
    claims: &[QM31; POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_CLAIMS_V1],
    point: usize,
    column: usize,
) -> QM31 {
    claims[point * POOL_V1_PAIR_FOREST_SELECTED_TERMINAL_COLUMNS_V1 + column]
}

fn semantic_packed(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1] {
    let mut packed = [QM31::ZERO; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1];
    add_schedule_lanes(&mut packed, public, openings, selectors);
    add_path_lanes(&mut packed, openings, selectors);
    add_value_lanes(&mut packed, openings, selectors);
    add_occupancy_lanes(&mut packed, public, openings, selectors);
    #[cfg(not(feature = "optimized-terminal"))]
    add_preweighted(
        &mut packed,
        84,
        &public_digest_lanes(public, openings, selectors),
    );
    #[cfg(feature = "optimized-terminal")]
    {
        let digests = public_digest_packed(public, openings, selectors);
        packed[84 / 4] = packed[84 / 4].add(digests[0]);
        packed[84 / 4 + 1] = packed[84 / 4 + 1].add(digests[1]);
    }
    let asset_difference = openings.z[1].sub(lift_m31(public.asset_id));
    let input_asset = selectors.row(2 * 16 + 12).mul(asset_difference);
    let output_scalar = selectors.row(31 * 16 + 12).mul(asset_difference);
    let private_transfer_term = selectors.row(28 * 16 + 12).mul(asset_difference);
    let withdrawal_amount_value = public.withdrawal_amount.unwrap_or(0);
    let withdrawal_term = selectors
        .row(16 * VALUE_AUXILIARY_BLOCK + 2)
        .mul(openings.z[10].sub(lift_m31(M31(withdrawal_amount_value))));
    let scalars = scalar_lanes(
        public.variant,
        public.withdrawal_amount.is_some(),
        input_asset,
        output_scalar,
        private_transfer_term,
        withdrawal_term,
    );
    add_preweighted(&mut packed, 92, &scalars);
    packed
}

pub(crate) fn evaluate_with_selectors(
    openings: &[QM31; POSEIDON2_WIDTH],
    h1_z: QM31,
    selectors: &Selectors,
    lambda: QM31,
    chi: QM31,
    append_index: u64,
    variant: PoolV1PairForestCompiledVariantV1,
) -> PoolV1PairForestCompiledCopyTerminalV1 {
    let patterns = pattern_values(openings, lambda);
    let mut row = CopyRowExtension {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [QM31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [QM31::ZERO; 2],
    };
    #[cfg(all(
        feature = "optimized-terminal",
        not(feature = "optimized-terminal")
    ))]
    let mut selector_cache = EndpointSelectorCache::new();
    #[cfg(all(
        feature = "optimized-terminal",
        not(feature = "optimized-terminal")
    ))]
    let mut tag_values = [QM31::ZERO; 4];
    #[cfg(all(
        feature = "optimized-terminal",
        not(feature = "optimized-terminal")
    ))]
    let mut pattern_selectors = [QM31::ZERO; 26];
    #[cfg(feature = "optimized-terminal")]
    let mut selector_tensor_scratch = [QM31::ZERO; COPY_SELECTOR_TENSOR_SCRATCH];
    let mut link_index = 0usize;
    while link_index < POOL_V1_PAIR_FOREST_COPY_TERMINAL_LINKS_V1 {
        let link = constants::COPY_LINKS[link_index];
        let weight = link_weight(link, append_index, variant);
        #[cfg(all(
            not(feature = "optimized-terminal"),
            not(feature = "optimized-terminal")
        ))]
        #[cfg(not(feature = "optimized-terminal"))]
        {
            accumulate_endpoint(
                &mut row.producer_values,
                &mut row.producer_weights,
                link.producer,
                link.tag,
                weight,
                &patterns,
                selectors,
            );
            accumulate_endpoint(
                &mut row.consumer_values,
                &mut row.consumer_weights,
                link.consumer,
                link.tag,
                weight,
                &patterns,
                selectors,
            );
        }
        #[cfg(all(
            not(feature = "optimized-terminal"),
            not(feature = "optimized-terminal")
        ))]
        #[cfg(feature = "optimized-terminal")]
        {
            accumulate_endpoint(
                &mut row.producer_values,
                &mut row.producer_weights,
                link.producer,
                link.tag,
                weight,
                &patterns,
                selectors,
                &mut selector_cache,
            );
            accumulate_endpoint(
                &mut row.consumer_values,
                &mut row.consumer_weights,
                link.consumer,
                link.tag,
                weight,
                &patterns,
                selectors,
                &mut selector_cache,
            );
        }
        #[cfg(all(
            feature = "optimized-terminal",
            not(feature = "optimized-terminal")
        ))]
        {
            accumulate_endpoint_pattern_basis(
                &mut tag_values,
                &mut pattern_selectors,
                &mut row.producer_weights,
                0,
                link.producer,
                link.tag,
                weight,
                selectors,
                #[cfg(feature = "optimized-terminal")]
                &mut selector_cache,
            );
            accumulate_endpoint_pattern_basis(
                &mut tag_values,
                &mut pattern_selectors,
                &mut row.consumer_weights,
                2,
                link.consumer,
                link.tag,
                weight,
                selectors,
                #[cfg(feature = "optimized-terminal")]
                &mut selector_cache,
            );
        }
        #[cfg(feature = "optimized-terminal")]
        {
            accumulate_endpoint_selector_tensor_basis(
                &mut selector_tensor_scratch,
                0,
                link.producer,
                link.tag,
                weight,
                selectors,
            );
            accumulate_endpoint_selector_tensor_basis(
                &mut selector_tensor_scratch,
                2,
                link.consumer,
                link.tag,
                weight,
                selectors,
            );
        }
        link_index += 1;
    }
    #[cfg(all(
        feature = "optimized-terminal",
        not(feature = "optimized-terminal")
    ))]
    {
        let values = finish_pattern_basis_values(tag_values, pattern_selectors, &patterns);
        row.producer_values = [values[0], values[1]];
        row.consumer_values = [values[2], values[3]];
    }
    #[cfg(feature = "optimized-terminal")]
    {
        let (values, weights) =
            finish_selector_tensor_basis(&selector_tensor_scratch, &patterns, selectors);
        row.producer_values = [values[0], values[1]];
        row.consumer_values = [values[2], values[3]];
        row.producer_weights = [weights[0], weights[1]];
        row.consumer_weights = [weights[2], weights[3]];
    }
    let active = selectors.active();
    PoolV1PairForestCompiledCopyTerminalV1 {
        residual: active.mul(copy_residual(row, h1_z, chi)),
        active,
    }
}

pub(crate) fn mul(self, rhs: QM31) -> QM31 {
        let m0 = prepared_component_mul(self.components[0], rhs.c0);
        let m1 = prepared_component_mul(self.components[1], rhs.c1);
        let m2 = prepared_component_mul(self.components[2], rhs.c0.add(rhs.c1));
        QM31 {
            c0: m0.add(cm31_mul_r(m1)),
            c1: m2.sub(m0).sub(m1),
        }
    }

fn empty_root(level: usize) -> Digest {
    let words = constants::POOL_V1_PAIR_EMPTY_ROOTS_V1[level];
    [M31(words[0]), M31(words[1]), M31(words[2]), M31(words[3]),
     M31(words[4]), M31(words[5]), M31(words[6]), M31(words[7])]
}

fn sum_high(selectors: &Selectors, ranges: &[core::ops::Range<usize>]) -> QM31 {
    let mut sum = QM31::ZERO;
    for range in ranges {
        for block in range.clone() {
            sum = sum.add(selectors.high[block]);
        }
    }
    sum
}

fn add_path_lanes(
    packed: &mut [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1],
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) {
    let path_selector = sum_high(selectors, &[57..63]).mul(
        selectors.low[1]
            .add(selectors.low[5])
            .add(selectors.low[9])
            .add(selectors.low[13]),
    );
    #[cfg(not(feature = "optimized-terminal"))]
    let path = path_lanes_literal(path_selector, openings);
    #[cfg(feature = "optimized-terminal")]
    let path = path_lanes_factored(path_selector, openings);
    add_preweighted(packed, 32, &path);
}

fn add_value_lanes(
    packed: &mut [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1],
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) {
    let value_selectors =
        [selectors.row(16 * VALUE_AUXILIARY_BLOCK),
         selectors.row(16 * VALUE_AUXILIARY_BLOCK + 2),
         selectors.row(16 * VALUE_AUXILIARY_BLOCK + 4)];
    let range_selector = QM31::ZERO
        .add(value_selectors[0])
        .add(value_selectors[1])
        .add(value_selectors[2]);
    let mut range = [QM31::ZERO; 33];
    let mut index = 0usize;
    while index < 10 {
        range[index] = openings.z[index].square().sub(openings.z[index]);
        index += 1;
    }
    index = 0;
    while index < 10 {
        range[10 + index] = openings.succ_z[index]
            .square()
            .sub(openings.succ_z[index]);
        index += 1;
    }
    index = 0;
    while index < 10 {
        range[20 + index] = openings.xor12_z[index]
            .square()
            .sub(openings.xor12_z[index]);
        index += 1;
    }
    let reconstructed = reconstruct_10(&openings.z)
        .add(reconstruct_10(&openings.succ_z).mul_m31(M31(1 << 10)))
        .add(reconstruct_10(&openings.xor12_z).mul_m31(M31(1 << 20)));
    range[30] = openings.z[10].sub(reconstructed);
    range[31] = openings.succ_z[10];
    range[32] = openings.xor12_z[10];
    #[cfg(not(feature = "optimized-terminal"))]
    {
        for residual in &mut range {
            *residual = range_selector.mul(*residual);
        }
        add_preweighted(packed, 49, &range);
    }
    #[cfg(feature = "optimized-terminal")]
    add_preweighted_shared_selector(packed, 49, &range, range_selector);

    let conservation_selector = selectors.row(16 * VALUE_AUXILIARY_BLOCK + 6);
    let conservation = [
        conservation_selector.mul(openings.z[0].sub(openings.z[1]).sub(openings.z[2])),
        conservation_selector.mul(openings.succ_z[0].sub(openings.succ_z[1])),
    ];
    add_preweighted(packed, 82, &conservation);
}

fn public_digest_lanes(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> [QM31; DIGEST_ELEMS] {
    let mut digests = [QM31::ZERO; DIGEST_ELEMS];
    add_digest_binding(
        &mut digests,
        selectors.row(56 * 16 + 11),
        &openings.z,
        0,
        &public.anchor,
        false,
    );
    add_digest_binding(
        &mut digests,
        selectors.row(26 * 16 + 11),
        &openings.z,
        0,
        &public.nullifier,
        false,
    );
    if let Some(recipient) = public.recipient {
        add_digest_binding(
            &mut digests,
            selectors.row(29 * 16 + 11),
            &openings.z,
            0,
            &recipient,
            false,
        );
    }
    add_digest_binding(
        &mut digests,
        selectors.row(32 * 16 + 11),
        &openings.z,
        0,
        &public.change,
        false,
    );

    let source = public.transition.live_snapshot;
    let after = public.transition.candidate_afterstate;
    for level in 0..20 {
        let block = 34 + level;
        if ((source.next_pair_index >> level) & 1) == 0 {
            add_digest_binding(
                &mut digests,
                selectors.row(block * 16),
                &openings.z,
                RATE,
                &empty_root(level),
                true,
            );
        } else {
            add_digest_binding(
                &mut digests,
                selectors.row(block * 16 + 12),
                &openings.z,
                0,
                &source.frontier[level],
                false,
            );
        }
    }
    add_digest_binding(
        &mut digests,
        selectors.row(53 * 16 + 11),
        &openings.z,
        0,
        &after.next_root,
        false,
    );
    let carry = bounded_append_carry(source.next_pair_index);
    if carry < 20 {
        add_digest_binding(
            &mut digests,
            selectors.row((33 + carry) * 16 + 11),
            &openings.z,
            0,
            &after.next_frontier[carry],
            false,
        );
    }
    digests
}

fn add_preweighted<const N: usize>(
    packed: &mut [QM31; POOL_V1_PAIR_FOREST_PACKED_SEMANTIC_LANES_V1],
    start: usize,
    values: &[QM31; N],
) {
    let first = start / 4;
    let last = (start + N - 1) / 4;
    for group in first..=last {
        let lanes: [QM31; 4] = qm31_array!(4, slot, {
            let source = 4 * group + slot;
            if source >= start && source < start + N {
                values[source - start]
            } else {
                QM31::ZERO
            }
        });
        packed[group] = packed[group].add(qm31_pack_base4(&lanes));
    }
}

pub(crate) fn row(&self, row: usize) -> QM31 {
        debug_assert!(row < POOL_V1_PAIR_FOREST_COPY_TERMINAL_ROWS_V1);
        self.high[row >> 4].mul(self.low[row & 15])
    }

fn copy_residual(row: CopyRowExtension, helper: QM31, chi: QM31) -> QM31 {
    let denominators = [
        chi.sub(row.producer_values[0]),
        chi.sub(row.producer_values[1]),
        chi.sub(row.consumer_values[0]),
        chi.sub(row.consumer_values[1]),
    ];
    let producer_denominator = denominators[0].mul(denominators[1]);
    let consumer_denominator = denominators[2].mul(denominators[3]);
    let producer_numerator = row.producer_weights[0]
        .mul(denominators[1])
        .add(row.producer_weights[1].mul(denominators[0]));
    let consumer_numerator = row.consumer_weights[0]
        .mul(denominators[3])
        .add(row.consumer_weights[1].mul(denominators[2]));
    producer_denominator
        .mul(helper.mul(consumer_denominator).add(consumer_numerator))
        .sub(consumer_denominator.mul(producer_numerator))
}

fn accumulate_endpoint(
    values: &mut [QM31; 2],
    weights: &mut [QM31; 2],
    endpoint: CompiledPoolV1PairForestEndpoint,
    tag: u32,
    weight: M31,
    patterns: &[QM31; POOL_V1_PAIR_FOREST_COPY_TERMINAL_PATTERNS_V1],
    selectors: &Selectors,
    #[cfg(feature = "optimized-terminal")]
    selector_cache: &mut EndpointSelectorCache,
) {
    #[cfg(not(feature = "optimized-terminal"))]
    let selector = selectors.row(usize::from(endpoint.row));
    #[cfg(feature = "optimized-terminal")]
    let selector = selector_cache.selector(endpoint.row, selectors);
    let slot = usize::from(endpoint.slot);
    #[cfg(not(feature = "optimized-terminal"))]
    {
        weights[slot] = weights[slot].add(selector.mul_m31(weight));
    }
    #[cfg(feature = "optimized-terminal")]
    {
        weights[slot] = add_binary_weight(weights[slot], selector, weight);
    }
    let compressed = lift_m31(M31(tag)).add(patterns[usize::from(endpoint.pattern)]);
    values[slot] = values[slot].add(selector.mul(compressed));
}

fn prepared_component_mul(left: [M31; 3], right: CM31) -> CM31 {
    let m0 = left[0].mul(right.a);
    let m1 = left[1].mul(right.b);
    let m2 = left[2].mul(right.a.add(right.b));
    CM31 {
        a: m0.sub(m1),
        b: m2.sub(m0).sub(m1),
    }
}

fn expand<const N: usize>(point: &[QM31; 10], start: usize, count: usize) -> [QM31; N] {
        let mut weights = [QM31::ZERO; N];
        weights[0] = QM31::ONE;
        let mut len = 1usize;
        let mut coordinate = start;
        while coordinate < start + count {
            let prepared = PreparedQm31Multiplier::new(point[coordinate]);
            let mut index = len;
            while index > 0 {
                index -= 1;
                let parent = weights[index];
                let right = prepared.mul(parent);
                weights[2 * index] = parent.sub(right);
                weights[2 * index + 1] = right;
            }
            len *= 2;
            coordinate += 1;
        }
        weights
    }

fn semantic_initial_and_absorption(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> ([QM31; 16], [QM31; 16]) {
    let nodes = sum_high(selectors, &[4..25, 33..57]);
    let first_common = selectors.high[0]
        .add(selectors.high[1])
        .add(selectors.high[25])
        .add(selectors.high[30]);
    let (transfer_first, fixed, private_chunk_eight, private_chunk_two) =
        initial_variant_selectors(
            public.variant,
            selectors.high[27],
            selectors.high[28],
            selectors.high[29],
        );
    let full_initial_selector = selectors.low[0].mul(first_common.add(transfer_first).add(fixed));
    let rate_initial_selector = selectors.low[0].mul(nodes);
    let full = PreparedQm31Multiplier::new(full_initial_selector);
    let full_or_rate =
        PreparedQm31Multiplier::new(full_initial_selector.add(rate_initial_selector));
    let mut initial = qm31_array!(16, lane, {
        if lane < RATE {
            full_or_rate.mul(openings.z[lane])
        } else {
            full.mul(openings.z[lane])
        }
    });
    let note_first = selectors.high[1]
        .add(selectors.high[30])
        .add(transfer_first);
    let domain = selectors.high[0]
        .mul_m31(DOMAIN_OWNER_KEY)
        .add(note_first.mul_m31(DOMAIN_NOTE))
        .add(selectors.high[25].mul_m31(DOMAIN_NULLIFIER));
    let length = selectors.high[0]
        .mul_m31(M31(8))
        .add(note_first.mul_m31(M31(18)))
        .add(selectors.high[25].mul_m31(M31(16)));
    initial[RATE] = initial[RATE].sub(selectors.low[0].mul(domain));
    initial[RATE + 1] = initial[RATE + 1].sub(selectors.low[0].mul(length));

    let mut chunk_eight = selectors.high[0]
        .add(selectors.high[1])
        .add(selectors.high[2])
        .add(selectors.high[25])
        .add(selectors.high[26])
        .add(selectors.high[30])
        .add(selectors.high[31]);
    let mut chunk_two = selectors.high[3].add(selectors.high[32]);
    chunk_eight = chunk_eight.add(private_chunk_eight);
    chunk_two = chunk_two.add(private_chunk_two);
    #[cfg(not(feature = "optimized-terminal"))]
    let absorption = absorption_lanes_literal(
        selectors.low[12],
        fixed,
        chunk_two,
        chunk_eight,
        nodes,
        &openings.z,
    );
    #[cfg(feature = "optimized-terminal")]
    let absorption = absorption_lanes_factored(
        selectors.low[12],
        fixed,
        chunk_two,
        chunk_eight,
        nodes,
        &openings.z,
    );
    (initial, absorption)
}

fn path_lanes_literal(path_selector: QM31, openings: &StateOnlyPoseidonOpenings) -> [QM31; 17] {
    let bit = openings.z[0];
    let mut path = [QM31::ZERO; 17];
    path[0] = path_selector.mul(bit.mul(bit.sub(QM31::ONE)));
    for lane in 0..DIGEST_ELEMS {
        let current = openings.z[1 + lane];
        path[1 + lane] = path_selector
            .mul(QM31::ONE.sub(bit))
            .mul(openings.succ_z[lane].sub(current));
        path[1 + DIGEST_ELEMS + lane] = path_selector
            .mul(bit)
            .mul(openings.succ_z[RATE + lane].sub(current));
    }
    path
}

fn reconstruct_10(view: &[QM31; 16]) -> QM31 {
    let mut acc = view[9];
    let mut index = 9usize;
    while index > 0 {
        index -= 1;
        acc = acc.add(acc).add(view[index]);
    }
    acc
}

fn occupancy_lanes_literal(
    input_occupancy: QM31,
    output_occupancy: QM31,
    expected_output: M31,
    opened: &[QM31; 16],
) -> [QM31; 12] {
    let occupied = opened[0];
    let inverse = opened[1];
    let one_minus = QM31::ONE.sub(occupied);
    let mut occupancy = [QM31::ZERO; 12];
    let both = input_occupancy.add(output_occupancy);
    occupancy[0] = both.mul(occupied.mul(occupied.sub(QM31::ONE)));
    occupancy[1] = both.mul(opened[9].mul(inverse).sub(occupied));
    occupancy[2] = both.mul(one_minus.mul(inverse));
    for lane in 0..DIGEST_ELEMS {
        occupancy[3 + lane] = both.mul(one_minus.mul(opened[2 + lane]));
    }
    occupancy[11] = input_occupancy
        .mul(opened[10].mul(one_minus))
        .add(output_occupancy.mul(occupied.sub(lift_m31(expected_output))));
    occupancy
}

fn add_digest_binding(
    output: &mut [QM31; DIGEST_ELEMS],
    selector: QM31,
    opened: &[QM31; POSEIDON2_WIDTH],
    start: usize,
    expected: &Digest,
    right_tweak: bool,
) {
    for lane in 0..DIGEST_ELEMS {
        let mut target = expected[lane];
        if right_tweak && lane + 1 == DIGEST_ELEMS {
            target = target.add(MERKLE_NODE_COMPRESSION_V3_TWEAK);
        }
        output[lane] = output[lane].add(selector.mul(opened[start + lane].sub(lift_m31(target))));
    }
}

pub(crate) fn qm31_pack_base4(values: &[QM31]) -> QM31 {
    assert!(values.len() <= 4);
    let mut padded = [QM31::ZERO; 4];
    let mut i = 0usize;
    while i < values.len() { padded[i] = values[i]; i += 1; }
    let [v0, v1, v2, v3] = padded;
    let p = u64::from(P);


    // Multiplication by u sends (c0,c1) to ((2+i)c1,c0), while
    // multiplication by i sends (a,b) to (-b,a).
    let c0_a = terminal_limb(v0.c0.a)
        + (p - terminal_limb(v1.c0.b))
        + 2 * terminal_limb(v2.c1.a)
        + (p - terminal_limb(v2.c1.b))
        + (p - terminal_limb(v3.c1.a))
        + (2 * p - 2 * terminal_limb(v3.c1.b));
    let c0_b = terminal_limb(v0.c0.b)
        + terminal_limb(v1.c0.a)
        + terminal_limb(v2.c1.a)
        + 2 * terminal_limb(v2.c1.b)
        + 2 * terminal_limb(v3.c1.a)
        + (p - terminal_limb(v3.c1.b));
    let c1_a = terminal_limb(v0.c1.a) + (p - terminal_limb(v1.c1.b)) + terminal_limb(v2.c0.a) + (p - terminal_limb(v3.c0.b));
    let c1_b = terminal_limb(v0.c1.b) + terminal_limb(v1.c1.a) + terminal_limb(v2.c0.b) + terminal_limb(v3.c0.a);

    QM31 {
        c0: CM31::new(M31::reduce_u64(c0_a), M31::reduce_u64(c0_b)),
        c1: CM31::new(M31::reduce_u64(c1_a), M31::reduce_u64(c1_b)),
    }
}

fn pattern_values_literal(
    openings: &[QM31; POSEIDON2_WIDTH],
    lambda: QM31,
) -> [QM31; POOL_V1_PAIR_FOREST_COPY_TERMINAL_PATTERNS_V1] {
    let mut powers = [QM31::ZERO; POSEIDON2_WIDTH];
    let mut power = lambda;
    let mut limb = 0usize;
    while limb < POSEIDON2_WIDTH {
        powers[limb] = power;
        power = power.mul(lambda);
        limb += 1;
    }
    let mut result = [QM31::ZERO; POOL_V1_PAIR_FOREST_COPY_TERMINAL_PATTERNS_V1];
    let mut pattern_index = 0usize;
    while pattern_index < POOL_V1_PAIR_FOREST_COPY_TERMINAL_PATTERNS_V1 {
        let pattern = constants::COPY_PATTERNS[pattern_index];
        let mut value = QM31::ZERO;
        limb = 0;
        while limb < POSEIDON2_WIDTH {
            if pattern.kinds[limb] == 1 {
                let source = openings[usize::from(pattern.columns[limb])]
                    .add(lift_m31(M31(pattern.offsets[limb])));
                value = value.add(powers[limb].mul(source));
            }
            limb += 1;
        }
        result[pattern_index] = value;
        pattern_index += 1;
    }
    result
}

fn active_literal(&self) -> QM31 {
        let mut sum = QM31::ZERO;
        let mut block = 0usize;
        while block < 64 {
            let mask = constants::ACTIVE_ROW_MASKS[block];
            if mask != 0 {
                sum = sum.add(self.high[block].mul(selector_mask_sum_16(&self.low, mask)));
            }
            block += 1;
        }
        sum
    }

fn absorption_lanes_literal(
    low: QM31,
    fixed: QM31,
    chunk_two: QM31,
    chunk_eight: QM31,
    nodes: QM31,
    openings: &[QM31; 16],
) -> [QM31; 16] {
    qm31_array!(16, lane, {
        let blocks = if lane < 2 {
            fixed
        } else if lane < RATE {
            fixed.add(chunk_two)
        } else {
            fixed.add(chunk_two).add(chunk_eight).add(nodes)
        };
        low.mul(blocks).mul(openings[lane])
    })
}

fn selector_mask_sum_16(values: &[QM31; 16], mut mask: u16) -> QM31 {
    let complement = mask.count_ones() > 8;
    if complement {
        mask = !mask;
    }
    let mut sum = if complement { QM31::ONE } else { QM31::ZERO };
    while mask != 0 {
        let index = mask.trailing_zeros() as usize;
        sum = if complement {
            sum.sub(values[index])
        } else {
            sum.add(values[index])
        };
        mask &= mask - 1;
    }
    sum
}
